$ErrorActionPreference='Stop';
try {
Write-Host '水泳大会運営 v2.7.16 更新前修復' -ForegroundColor Cyan;
$identity=[Security.Principal.WindowsIdentity]::GetCurrent();$principal=New-Object Security.Principal.WindowsPrincipal($identity);
Assert-Swim ($principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) 'このウィンドウを閉じ、修復.cmdを右クリックして「管理者として実行」してください。別アカウントでの実行はしないでください。';
Assert-Swim ($ExecutionContext.SessionState.LanguageMode -eq 'FullLanguage') 'PCの実行制限により安全な修復を実施できません。制限を変更せず管理者へ相談してください。';
$session=(Get-Process -Id $PID).SessionId;$shells=@(Get-CimInstance Win32_Process|Where-Object {$_.Name -eq 'explorer.exe' -and $_.SessionId -eq $session});$owners=@($shells|ForEach-Object {(Invoke-CimMethod -InputObject $_ -MethodName GetOwnerSid).Sid}|Sort-Object -Unique);Assert-Swim ($owners.Count -eq 1 -and $owners[0] -eq $identity.User.Value) 'デスクトップと同じ利用者であることを確認できません。別アカウントで修復しないでください。';
$plan=Get-Content -LiteralPath (Join-Path $env:SWIM_REPAIR_KIT 'repair-plan.json') -Raw|ConvertFrom-Json;
Assert-Swim ($plan.originalSHA256 -eq '59ce655aedec7a506aac3ff6458da1fa25e76b28271ccc2fd2c09099bda6f3e3') '対応しない修復情報です。';
$expectedFixed='FIXED_SHA256';
Assert-Swim ($plan.repairedSHA256 -eq $expectedFixed) '修復情報が一致しません。';
$reg=Get-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\d4281aaa-4df2-5eb1-ac49-2931a1a9158d';
Assert-Swim ($reg.DisplayVersion -eq '2.7.16') '修復対象はv2.7.16の全ユーザー用に限定されています。ほかの版は変更しません。';
$install=Join-Path $env:ProgramFiles 'SwimMeetManager';$target=Join-Path $install 'Uninstall SwimMeetManager.exe';
Assert-Swim ($reg.UninstallString -eq ('{0}{1}{0} /allusers' -f [char]34,$target)) '登録された削除プログラムと修復先が一致しません。';Safe-Swim $install;Safe-Swim $target;
$running=@(Get-CimInstance Win32_Process|Where-Object {$_.Name -match '^(SwimMeetManager(?:-Setup.*)?|Uninstall SwimMeetManager|old-uninstaller)\.exe$'});
Assert-Swim ($running.Count -eq 0) 'アプリとSetupを完全終了してください。プロセスを強制終了せず修復を中止しました。';
$current=Hash-Swim $target;if($current -eq $expectedFixed){Write-Host '修復済みです。新しいSetupを実行してください。' -ForegroundColor Green;exit 0};
Assert-Swim ($current -eq $plan.originalSHA256) '対象ファイルのハッシュが一致しません。変更せず停止します。';
$original=[IO.File]::ReadAllBytes($target);$fixed=[byte[]]$original.Clone();$end=$original.Length;
Assert-Swim ($end -eq $plan.bytes) '対象ファイルの長さが違います。';
foreach($op in $plan.operations){$before=[Convert]::FromBase64String($op.before);$after=[Convert]::FromBase64String($op.after);$at=[int]$op.offset;Assert-Swim ($before.Length -eq $after.Length -and $at -ge 34816 -and $at+$after.Length -le 57856) 'アイコン範囲以外の変更を拒否しました。';for($n=0;$n -lt $before.Length;$n++){Assert-Swim ($fixed[$at+$n]-eq $before[$n]) 'アイコンの元データが違います。';$fixed[$at+$n]=$after[$n]}};
$sha=[Security.Cryptography.SHA256]::Create();try{$fixedHash=([BitConverter]::ToString($sha.ComputeHash($fixed))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};
Assert-Swim ($fixedHash -eq $expectedFixed) '修復後の全体ハッシュが一致しません。変更せず停止します。';
Assert-Swim ([BitConverter]::ToUInt32($fixed,$end-4)-eq [BitConverter]::ToUInt32($original,$end-4)) '元の整合性チェック値を変更する修復は拒否しました。';
$data=Join-Path $env:APPDATA 'SwimMeetManager\data';Safe-Swim $data;Assert-Swim (-not(Test-Path -LiteralPath (Join-Path (Split-Path $data) 'desktop-service.write-lock'))) '内部処理のロックが残っています。元データを変更せず中止します。';
Assert-Swim (Test-Path -LiteralPath (Join-Path $data 'swim-data.json') -PathType Leaf) '現在のユーザーの大会データが見つかりません。別アカウントで実行していないか確認してください。';
$envelope=Get-Content -LiteralPath (Join-Path $data 'swim-data.json') -Raw|ConvertFrom-Json;
Assert-Swim ($envelope.format -eq 'swim-encrypted-v1' -and $envelope.algorithm -eq 'aes-256-gcm') '暗号化データの形式を確認できません。';
$key=Join-Path $data 'keys\storage.key';Assert-Swim ((Get-Content -LiteralPath $key -Raw).Trim() -match '^[0-9a-fA-F]{64}$') '暗号鍵が確認できません。';
$manifest=@(Manifest-Swim $data);
Safe-Swim $env:LOCALAPPDATA;$base=Join-Path $env:LOCALAPPDATA 'SwimMeetManager-InstallerRecovery';$backup=Join-Path $base 'v2.7.16';
if(Test-Path -LiteralPath $base){Safe-Swim $base};if(Test-Path -LiteralPath $backup){Verify-SwimBackup $data $backup $manifest $plan.originalSHA256;Write-Host '前回のバックアップは現在のデータと一致しています。削除せず再利用します。'};
$stage=Join-Path $install 'Uninstall SwimMeetManager.repair.tmp';$rollback=Join-Path $install 'Uninstall SwimMeetManager.repair-original.bak';
if(Test-Path -LiteralPath $stage){Safe-Swim $stage;Assert-Swim ((Hash-Swim $stage)-eq $expectedFixed) '残った一時ファイルが違います。削除せず停止します。';Write-Host '前回の修復用一時ファイルも一致しています。再利用します。'};
Write-Host ('対象：'+$target);Write-Host ('大会データ：'+$data);Write-Host ('バックアップ：'+$backup);Write-Host ('利用者：'+$identity.Name);
Write-Host '大会データと鍵をバックアップした後、削除プログラムのアイコン部分だけ修復します。大会データ・登録情報は変更しません。別の管理者アカウントの場合は中止してください。' -ForegroundColor Yellow;
if($env:SWIM_REPAIR_PHASE -eq 'preview'){exit 42};
Assert-Swim ($env:SWIM_REPAIR_PHASE -eq 'commit' -and $env:SWIM_REPAIR_APPROVAL -ceq 'REPAIR') 'キャンセルしました。';
if(-not(Test-Path -LiteralPath $base)){[IO.Directory]::CreateDirectory($base)|Out-Null};
Repair-Swim $data $backup $target $stage $rollback $fixed $plan.originalSHA256 $expectedFixed $true|Out-Null;
Write-Host '修復が完了しました。新しいv2.8.5のSetupを実行してください。' -ForegroundColor Green;Write-Host ('復元用バックアップ：'+$backup);
} catch {Write-Host ('停止：'+$_.Exception.Message) -ForegroundColor Red;exit 1};
